using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Web.Script.Serialization;
// Owner declarations only. Lock/CAS preserve cooperating editors; no market approval.
public static class DecisionStore {
 public const string RecoveryFile="decision-recovery-v1.json";
 public static Dictionary<string,object> Read(string root){string path=Path.Combine(root,"review-notes.json");return File.Exists(path)?LocalJson.ReadObject(path):new Dictionary<string,object>();}
 public static Dictionary<string,object> ProtectedDecisions(string root){var wrap=LocalJson.ReadObject(Path.Combine(root,RecoveryFile));string raw=ManualHypotheses.S(wrap,"payload_json");if(ProvenanceAudit.Sha(raw)!=ManualHypotheses.S(wrap,"payload_sha256"))throw new InvalidDataException("Decision recovery payload changed");var value=LocalJson.ParseObject(raw);if(ManualHypotheses.S(value,"schema")!="reveng-decision-recovery-v1"||ManualHypotheses.S(value,"status")!="RECOVERY_COPY_NOT_CURRENT_AUTHORITY"||!(ManualHypotheses.V(value,"decisions") is Dictionary<string,object>))throw new InvalidDataException("Decision recovery format invalid");if(value.Count!=4||value.Keys.Except(new[]{"schema","status","expected_primary_sha256","decisions"}).Any())throw new InvalidDataException("Decision recovery metadata invalid");object pin=ManualHypotheses.V(value,"expected_primary_sha256");if(pin!=null&&(!(pin is string)||!System.Text.RegularExpressions.Regex.IsMatch((string)pin,"^[0-9a-fA-F]{64}$")))throw new InvalidDataException("Decision recovery parent pin invalid");return (Dictionary<string,object>)value["decisions"];}
 static string RecoveryIssue(string root,Dictionary<string,object> primary){if(!File.Exists(Path.Combine(root,"review-notes.json"))&&File.Exists(LocalJson.BackupPath(Path.Combine(root,"review-notes.json"))))return "Primary decisions missing; previous file preserved for inspection, writes blocked. It is not guaranteed to contain the latest decision.";if(!File.Exists(Path.Combine(root,RecoveryFile)))return "";try{foreach(var p in ProtectedDecisions(root)){object found;if(!primary.TryGetValue(p.Key,out found)||!ProvenanceAudit.Equal(found,p.Value))return "Conflict or interrupted commit: primary differs from protected decisions. No automatic merge. Review "+Path.Combine(root,RecoveryFile)+" and review-notes.json; further writes are blocked.";}return "";}catch(Exception ex){return "Decision recovery is unreadable; bytes preserved, writes blocked: "+ex.Message;}}
 public static string RecoveryIssue(string root){try{return RecoveryIssue(root,Read(root));}catch(Exception ex){return "Primary decisions unreadable; existing files preserved: "+ex.Message+(File.Exists(Path.Combine(root,RecoveryFile))?". Protected copy, not applied automatically: "+Path.Combine(root,RecoveryFile):"");}}
 public static string DescribeRecovery(string root,string id,string revision){
  var b=new StringBuilder();string issue=RecoveryIssue(root);if(issue=="")return "";
  b.AppendLine("DECISION RECOVERY CONFLICT / Конфликт сохранённых решений").AppendLine(issue);
  b.AppendLine("Сохранённые варианты ниже доступны для проверки. Они не применены автоматически; запись заблокирована. Не удаляйте копии до сверки.");
  Action<string,Dictionary<string,object>> append=(label,data)=>{b.AppendLine(label);if(data.Count==0)b.AppendLine("No saved entries / сохранённых записей нет.");foreach(var entry in data.OrderBy(p=>p.Key,StringComparer.Ordinal)){var value=ManualHypotheses.D(entry.Value);b.AppendLine("Candidate ID: "+entry.Key+(entry.Key==id?" [selected / выбран]":""));b.AppendLine("Revision: "+ManualHypotheses.S(value,"revision_hash")+(entry.Key==id&&revision!=""?(ManualHypotheses.S(value,"revision_hash")==revision?" [selected revision]":" [different or unknown revision; not current approval]"):""));b.AppendLine(ManualHypotheses.Serialize(entry.Value));}};
  try{append("PRIMARY / текущий файл, при конфликте не подтверждён",Read(root));}catch(Exception ex){if(ex is OutOfMemoryException)throw;b.AppendLine("PRIMARY UNREADABLE: "+ex.Message);}
  string protectedPath=Path.Combine(root,RecoveryFile);if(File.Exists(protectedPath)){try{append("PROTECTED SNAPSHOT / защищённая копия; может содержать подготовленное, но не завершённое сохранение",ProtectedDecisions(root));}catch(Exception ex){if(ex is OutOfMemoryException)throw;b.AppendLine("PROTECTED SNAPSHOT UNREADABLE: "+ex.Message);}}
  string previous=LocalJson.BackupPath(Path.Combine(root,"review-notes.json"));if(File.Exists(previous)){try{append("PREVIOUS FILE / предыдущая копия; не гарантирует последнее решение и не применяется автоматически",LocalJson.ReadObject(previous));}catch(Exception ex){if(ex is OutOfMemoryException)throw;b.AppendLine("PREVIOUS FILE UNREADABLE: "+ex.Message);}}
  b.AppendLine("Если защищённая копия отсутствует или повреждена, последнее решение восстановить по previous нельзя гарантировать. Валидный устаревший primary без независимой защищённой копии не всегда распознаётся.");
  return b.ToString();
 }
 static void Protect(string root,Dictionary<string,object> data,string expected){string payload=ManualHypotheses.Serialize(new Dictionary<string,object>{{"schema","reveng-decision-recovery-v1"},{"status","RECOVERY_COPY_NOT_CURRENT_AUTHORITY"},{"expected_primary_sha256",expected},{"decisions",data}});string raw=ManualHypotheses.Serialize(new Dictionary<string,object>{{"payload_json",payload},{"payload_sha256",ProvenanceAudit.Sha(payload)}});if(new UTF8Encoding(false,true).GetByteCount(raw)>LocalJson.Limit)throw new InvalidDataException("Decision recovery exceeds8MiB; primary unchanged");string path=Path.Combine(root,RecoveryFile),temp=LocalJson.TemporaryPath(path);try{LocalJson.WriteTemporary(temp,raw);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 static object CanonicalValue(object value){var dict=value as Dictionary<string,object>;if(dict!=null)return dict.OrderBy(p=>p.Key,StringComparer.Ordinal).ToDictionary(p=>p.Key,p=>CanonicalValue(p.Value));if(value is IList)return ((IEnumerable)value).Cast<object>().Select(CanonicalValue).ToArray();return value;}
 public static string EntryPin(Dictionary<string,object> data,string id){object entry;return data.TryGetValue(id,out entry)?ProvenanceAudit.Sha(ManualHypotheses.Serialize(CanonicalValue(entry))):null;}
 static string FilePin(string path){return File.Exists(path)?LocalResearchController.Hash(path):null;}
 static string RawPin(byte[] raw){using(var hash=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(hash.ComputeHash(raw)).Replace("-","");}
 public static void RequirePublicationComplete(string root){if(File.Exists(Path.Combine(root,"candidate-publication.pending.json")))throw new InvalidDataException("Candidate publication pending; finish local recovery before recording a decision");}
 static string Candidate(string root,string id,string revision){RequirePublicationComplete(root);string path=Path.Combine(root,"candidates.json");byte[] bytes=LocalJson.ReadBytes(path,LocalJson.Limit);string raw=LocalJson.Decode(bytes);var rows=LocalJson.ParseValue(raw) as object[];if(rows==null)throw new InvalidDataException("Candidate inventory unreadable; decision not saved");var matches=rows.OfType<Dictionary<string,object>>().Where(r=>ManualHypotheses.S(r,"candidate_id")==id).ToArray();if(matches.Length!=1||ManualHypotheses.S(matches[0],"review_revision_hash")!=revision)throw new InvalidDataException("Candidate revision changed; reload before saving the decision");return RawPin(bytes);}
 public static string Save(string root,string id,string revision,string choice,string expectedEntry){
  ManualHypotheses.RequireWritable(root);if(String.IsNullOrWhiteSpace(id)||String.IsNullOrWhiteSpace(revision)||(choice!="keep"&&choice!="reject"))throw new InvalidDataException("Explicit candidate revision/choice required");
  string path=Path.Combine(root,"review-notes.json"),candidate=Path.Combine(root,"candidates.json");
  using(var gate=new FileStream(Path.Combine(root,".review-notes-write-v2.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
   byte[] captured=File.Exists(path)?LocalJson.ReadBytes(path,LocalJson.Limit):null;var data=captured==null?new Dictionary<string,object>():LocalJson.ParseObject(LocalJson.Decode(captured));string statePin=captured==null?null:RawPin(captured);string recovery=RecoveryIssue(root,data);if(recovery!="")throw new InvalidDataException(recovery);if(EntryPin(data,id)!=expectedEntry)throw new InvalidDataException("Decision changed in another editor; reload, existing work preserved");
   string sourcePin=Candidate(root,id,revision);
   data[id]=new Dictionary<string,object>{{"decision",choice},{"revision_hash",revision},{"decided_at",DateTime.UtcNow.ToString("o")},{"meaning","owner preference only; not customer/payment evidence"}};
   string raw=ManualHypotheses.Serialize(data);byte[] bytes=new UTF8Encoding(false,true).GetBytes(raw);if(bytes.Length>LocalJson.Limit)throw new InvalidDataException("Decision data exceeds8MiB; existing work preserved");
   string temp=LocalJson.TemporaryPath(path);
   try{using(var file=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);}
    RequirePublicationComplete(root);if(FilePin(path)!=statePin||FilePin(candidate)!=sourcePin)throw new InvalidDataException("Local files changed during save; existing work preserved");
    Protect(root,data,statePin);
    RequirePublicationComplete(root);if(FilePin(path)!=statePin||FilePin(candidate)!=sourcePin)throw new InvalidDataException("Local files changed during protected save; both snapshots preserved");
    if(File.Exists(path))File.Replace(temp,path,LocalJson.BackupPath(path));else File.Move(temp,path);
   }finally{if(File.Exists(temp))File.Delete(temp);}
   return EntryPin(data,id);
  }
 }
}
